/**
 * Visual Regression Baseline Tests
 * Generated by appcheck Step 13
 * Run: npx playwright test tests/visual_regression.spec.ts
 *
 * Baselines stored in: tests/visual_baselines/
 * To update baselines: npx playwright test tests/visual_regression.spec.ts --update-snapshots
 */

import { test, expect } from '@playwright/test';

const BASE_URL = process.env.PLAYWRIGHT_BASE_URL || 'https://missclubmodel.vercel.app';

// Pages to baseline (public, no auth required)
const PAGES = [
  { path: '/', label: 'homepage' },
  { path: '/events.html', label: 'events' },
  { path: '/contact.html', label: 'contact' },
  { path: '/terms.html', label: 'terms' },
  { path: '/privacy.html', label: 'privacy' },
  { path: '/design-system-builder.html', label: 'design-system' },
];

// Viewports to test
const VIEWPORTS = [
  { name: 'desktop', width: 1280, height: 720 },
  { name: 'tablet', width: 768, height: 1024 },
  { name: 'mobile', width: 375, height: 667 },
];

test.describe('Visual Regression Baselines', () => {
  for (const page of PAGES) {
    for (const viewport of VIEWPORTS) {
      test(`${page.label} @ ${viewport.name}`, async ({ browser }) => {
        const context = await browser.newContext({ viewport });
        const pageInstance = await context.newPage();

        await pageInstance.goto(`${BASE_URL}${page.path}`, {
          waitUntil: 'domcontentloaded',
          timeout: 15000,
        });

        // Wait for fonts and lazy-loaded images
        await pageInstance.waitForLoadState('networkidle').catch(() => {});
        await pageInstance.waitForTimeout(1500);

        // Use viewport screenshot to avoid WebKit 32767px fullPage limit
        const screenshot = await pageInstance.screenshot({ fullPage: false });
        expect(screenshot).toMatchSnapshot(`${page.label}-${viewport.name}.png`, {
          threshold: 0.1,
        });

        await context.close();
      });
    }
  }

  // Admin dashboard baseline (no auth — captures login screen)
  test('admin-dashboard @ desktop', async ({ browser }) => {
    const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
    const pageInstance = await context.newPage();

    await pageInstance.goto(`${BASE_URL}/admin`, {
      waitUntil: 'domcontentloaded',
      timeout: 15000,
    });

    await pageInstance.waitForLoadState('networkidle').catch(() => {});
    await pageInstance.waitForTimeout(1500);

    const screenshot = await pageInstance.screenshot({ fullPage: false });
    expect(screenshot).toMatchSnapshot('admin-dashboard-desktop.png', {
      threshold: 0.1,
    });

    await context.close();
  });
});
